import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

import { renderTree, renderTreeGrid } from './tree.js';

/**
 * Tree / TreeGrid robustness.
 *
 * The exact-output expectations below were generated by the original
 * recursive `renderNodes` walk before it was made iterative; they pin the
 * rendered structure and classes so the rewrite cannot drift. The recursive
 * walk threw `RangeError: Maximum call stack size exceeded` at ~3,000
 * levels of nesting — the depth cases here sit well past that.
 */

function deepChain(depth) {
  let node = { id: `n${depth - 1}`, label: `Node ${depth - 1}` };
  for (let i = depth - 2; i >= 0; i--) {
    node = { id: `n${i}`, label: `Node ${i}`, children: [node] };
  }
  return [node];
}

function everyId(depth) {
  return new Set(Array.from({ length: depth }, (_, i) => `n${i}`));
}

function count(haystack, needle) {
  return haystack.split(needle).length - 1;
}

describe('Tree output parity', () => {
  it('renders a mixed expanded/collapsed tree byte-identically', () => {
    const html = renderTree({
      items: [
        {
          id: 'a',
          label: 'Alpha',
          icon: '<svg></svg>',
          children: [
            { id: 'a1', label: 'Alpha One' },
            {
              id: 'a2',
              label: 'Alpha Two',
              children: [
                { id: 'a2i', label: 'Nested <Deep> & "quoted"' },
                { id: 'a2ii', label: 'Nested Two' },
              ],
            },
            { id: 'a3', label: 'Alpha Three' },
          ],
        },
        { id: 'b', label: 'Beta', children: [{ id: 'b1', label: 'Beta One' }] },
        { id: 'c', label: 'Gamma (leaf)' },
      ],
      expanded: new Set(['a', 'a2']),
      selected: 'a1',
      id: 'golden-tree',
    });
    assert.equal(
      html,
      '<ul data-bn="tree" id="golden-tree" role="tree"><li data-bn="tree-item" role="treeitem" tabindex="0" aria-expanded="true" aria-selected="false" data-node-id="a" data-level="0"><div data-bn="tree-item-content"><button data-bn="tree-toggle" aria-label="Collapse" type="button">▾</button><span data-bn="tree-icon"><svg></svg></span><span data-bn="tree-label">Alpha</span></div><ul data-bn="tree-children" role="group"><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="true" data-node-id="a1" data-level="1"><div data-bn="tree-item-content" data-selected><span data-bn="tree-indent"></span><span data-bn="tree-label">Alpha One</span></div></li><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-expanded="true" aria-selected="false" data-node-id="a2" data-level="1"><div data-bn="tree-item-content"><button data-bn="tree-toggle" aria-label="Collapse" type="button">▾</button><span data-bn="tree-label">Alpha Two</span></div><ul data-bn="tree-children" role="group"><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="false" data-node-id="a2i" data-level="2"><div data-bn="tree-item-content"><span data-bn="tree-indent"></span><span data-bn="tree-label">Nested &lt;Deep&gt; &amp; "quoted"</span></div></li><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="false" data-node-id="a2ii" data-level="2"><div data-bn="tree-item-content"><span data-bn="tree-indent"></span><span data-bn="tree-label">Nested Two</span></div></li></ul></li><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="false" data-node-id="a3" data-level="1"><div data-bn="tree-item-content"><span data-bn="tree-indent"></span><span data-bn="tree-label">Alpha Three</span></div></li></ul></li><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-expanded="false" aria-selected="false" data-node-id="b" data-level="0"><div data-bn="tree-item-content"><button data-bn="tree-toggle" aria-label="Expand" type="button">▸</button><span data-bn="tree-label">Beta</span></div><ul data-bn="tree-children" role="group" hidden><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="false" data-node-id="b1" data-level="1"><div data-bn="tree-item-content"><span data-bn="tree-indent"></span><span data-bn="tree-label">Beta One</span></div></li></ul></li><li data-bn="tree-item" role="treeitem" tabindex="-1" aria-selected="false" data-node-id="c" data-level="0"><div data-bn="tree-item-content"><span data-bn="tree-indent"></span><span data-bn="tree-label">Gamma (leaf)</span></div></li></ul>',
    );
  });

  it('renders a tree grid byte-identically', () => {
    const html = renderTreeGrid({
      columns: [
        { key: 'name', label: 'Name' },
        { key: 'size', label: 'Size' },
      ],
      items: [
        {
          name: 'Root',
          size: '10',
          children: [
            { name: 'Child A', size: '4' },
            { name: 'Child B', size: '6', children: [{ name: 'Grand <child>', size: '1' }] },
          ],
        },
        { name: 'Second root', size: '2' },
      ],
      expanded: new Set(['Root', 'Child B']),
      id: 'golden-grid',
    });
    assert.equal(
      html,
      '<table data-bn="treegrid" id="golden-grid" role="treegrid">\n  <thead><tr><th scope="col">Name</th><th scope="col">Size</th></tr></thead>\n  <tbody><tr data-bn="treegrid-row" data-node-id="Root" aria-level="1" aria-expanded="true" role="row" tabindex="0"><td><span data-level="0">▾ </span>Root</td><td>10</td></tr><tr data-bn="treegrid-row" data-node-id="Child A" aria-level="2" role="row" tabindex="-1"><td><span data-level="1">    </span>Child A</td><td>4</td></tr><tr data-bn="treegrid-row" data-node-id="Child B" aria-level="2" aria-expanded="true" role="row" tabindex="-1"><td><span data-level="1">  ▾ </span>Child B</td><td>6</td></tr><tr data-bn="treegrid-row" data-node-id="Grand &lt;child&gt;" aria-level="3" role="row" tabindex="-1"><td><span data-level="2">      </span>Grand &lt;child&gt;</td><td>1</td></tr><tr data-bn="treegrid-row" data-node-id="Second root" aria-level="1" role="row" tabindex="-1"><td><span data-level="0">  </span>Second root</td><td>2</td></tr></tbody>\n</table>',
    );
  });
});

describe('Tree pathological depth', () => {
  it('renders a 10,000-deep collapsed tree without overflowing the stack', () => {
    const html = renderTree({ items: deepChain(10_000), id: 'deep-collapsed' });
    assert.equal(count(html, 'role="treeitem"'), 10_000);
    assert.ok(html.includes('data-node-id="n9999" data-level="9999"'));
  });

  it('renders a 10,000-deep fully expanded tree without overflowing the stack', () => {
    const html = renderTree({
      items: deepChain(10_000),
      expanded: everyId(10_000),
      id: 'deep-expanded',
    });
    assert.equal(count(html, 'role="treeitem"'), 10_000);
    assert.ok(html.includes('data-node-id="n9999" data-level="9999"'));
  });

  it('renders a 3,000-deep fully expanded tree grid without overflowing the stack', () => {
    const html = renderTreeGrid({
      columns: [{ key: 'label', label: 'Name' }],
      items: deepChain(3_000),
      expanded: everyId(3_000),
      id: 'deep-grid',
    });
    assert.equal(count(html, 'data-bn="treegrid-row"'), 3_000);
    assert.ok(html.includes('data-node-id="n2999" aria-level="3000"'));
  });

  it('does not descend into a collapsed tree grid branch, however deep', () => {
    const html = renderTreeGrid({
      columns: [{ key: 'label', label: 'Name' }],
      items: deepChain(10_000),
      id: 'collapsed-grid',
    });
    assert.equal(count(html, 'data-bn="treegrid-row"'), 1);
  });
});
